const nj = require('numjs');

/**
 * Normalize each row of a 2D numeric table so each row sums to 1.
 * Rows with sum 0 are left as all zeros.
 *
 * @param {Array|nj.NdArray} input_data - 2D numeric array (JS array of arrays or nj ndarray)
 * @returns {nj.NdArray} - a numberjs ndarray containing the row-normalized data
 */
function normalizeRows(input_data) {
  const arr = nj.array(input_data);         // ensure we have an nj ndarray
  if (!Array.isArray(arr.shape) || arr.shape.length !== 2) {
    throw new Error('input_data must be a 2D array');
  }

  const [nRows, nCols] = arr.shape;
  const outRows = new Array(nRows);

  for (let i = 0; i < nRows; i++) {
    // get row as JS array
    const row = arr.pick(i).tolist();
    // compute sum
    let sum = 0;
    for (let v of row) sum += v;

    if (sum === 0) {
      // leave all-zero row unchanged (avoid division by zero)
      outRows[i] = new Array(nCols).fill(0);
    } else {
      // divide each element by the row sum
      outRows[i] = row.map(v => v / sum);
    }
  }

  return nj.array(outRows);
}

