 * - options:
 *     { zeroBased: boolean = false,   // rank starts at 0 if true, otherwise 1
 *       dense: boolean = true }       // dense ranking: equal values get same rank
 *
 * Returns an Array of ranks if input was an Array, or an Immutable.List if input was an Immutable.List.
 *
 * Complexity: O(n log n) due to a single sort.
 */
function rankList(lst0, options = {}) {
  const { zeroBased = false, dense = true } = options;

  // Detect Immutable.List and convert to plain array for processing
  const isImmutable = !!(lst0 && typeof lst0.toArray === 'function');
  const arr = isImmutable ? lst0.toArray() : Array.isArray(lst0) ? lst0.slice() : Array.from(lst0);

  // Pair values with original indices
  const pairs = arr.map((value, index) => ({ value, index }));

  // Sort pairs by value once
  pairs.sort((a, b) => {
    if (a.value < b.value) return -1;
    if (a.value > b.value) return 1;
    return 0;
  });

  // Assign ranks and place them back in original order
  const n = pairs.length;
  const ranks = new Array(n);
  let rank = zeroBased ? 0 : 1;

  for (let i = 0; i < n; i++) {
    if (i === 0) {
      // first element: current rank already set
    } else {
      if (dense) {
        // increment rank only when value changes
        if (pairs[i].value !== pairs[i - 1].value) rank++;
      } else {
