 * this returns S = sum_k ( X[k] outer-product Y[k] ).
 *
 * Returns an ml-matrices Matrix of size (m x n) where m = X[0].length and n = Y[0].length.
 *
 * @param {Array<Array<number>>} X - sequence of numeric arrays (vectors)
 * @param {Array<Array<number>>} Y - sequence of numeric arrays (vectors)
 * @returns {Matrix} - ml-matrices Matrix equal to the sum of outer products
 * @throws {Error} - on invalid input (mismatched lengths, non-numeric entries, inconsistent inner lengths)
 */
function sumOuterProducts(X, Y) {
  if (!Array.isArray(X) || !Array.isArray(Y)) {
    throw new Error('Both arguments must be arrays of numeric arrays.');
  }
  if (X.length !== Y.length) {
    throw new Error('The two sequences must have the same number of vectors.');
  }
  const pairs = X.length;
  if (pairs === 0) {
    // return empty matrix
    return new Matrix(0, 0);
  }

  // Validate first pair and infer dimensions
  if (!Array.isArray(X[0]) || !Array.isArray(Y[0])) {
    throw new Error('Each element of the sequences must be an array of numbers.');
  }
  const m = X[0].length;
  const n = Y[0].length;

  // Basic checks
  if (m === 0 || n === 0) {
    throw new Error('Vectors must be non-empty.');
  }

  // Initialize result as array-of-arrays with zeros
  const result = Array.from({ length: m }, () => new Array(n).fill(0));

  // Validate all pairs and accumulate outer products
  for (let k = 0; k < pairs; k++) {
    const a = X[k];
    const b = Y[k];

    if (!Array.isArray(a) || !Array.isArray(b)) {
      throw new Error(`Both X[${k}] and Y[${k}] must be arrays.`);
    }
    if (a.length !== m) {
      throw new Error(`All X vectors must have the same length (${m}); X[${k}] has length ${a.length}.`);
    }
    if (b.length !== n) {
      throw new Error(`All Y vectors must have the same length (${n}); Y[${k}] has length ${b.length}.`);
    }

    for (let i = 0; i < m; i++) {
      const ai = a[i];
      if (!Number.isFinite(ai)) {
        throw new Error(`X[${k}][${i}] is not a finite number.`);
      }
      for (let j = 0; j < n; j++) {
        const bj = b[j];
        if (!Number.isFinite(bj)) {
          throw new Error(`Y[${k}][${j}] is not a finite number.`);
        }
        result[i][j] += ai * bj;
      }
    }
  }

  return new Matrix(result);
}

