function replaceMissingWithColumnAverages(data) {
    // Check if the input is valid
    if (!Array.isArray(data) || data.length === 0) {
        throw new Error('Input must be a 2D array with numeric values.');
    }

    const numRows = data.length;
    const numCols = data[0].length;

    // Array to hold sums and counts of non-missing values
    const sums = new Array(numCols).fill(0);
    const counts = new Array(numCols).fill(0);

    // Calculate sums and counts for each column
    for (let row = 0; row < numRows; row++) {
        for (let col = 0; col < numCols; col++) {
            if (data[row][col] !== null && data[row][col] !== undefined) {
                sums[col] += data[row][col];
                counts[col]++;
            }
        }
    }

    // Calculate averages for each column
    const averages = sums.map((sum, idx) => counts[idx] > 0 ? sum / counts[idx] : null);

    // Replace missing entries with corresponding column averages
    for (let row = 0; row < numRows; row++) {
        for (let col = 0; col < numCols; col++) {
            if (data[row][col] === null || data[row][col] === undefined) {
                data[row][col] = averages[col];
            }
        }
    }

    return data;
