 *   conditionVal   - comparison value (will be passed as a parameter)
 *
 * Returns:
 *   the result of db.query (e.g., affected rows info) as returned by your client
 */
async function updateWhereGreater(db, table, colUpdate, newVal, colCondition, conditionVal) {
  if (!db || typeof db.query !== 'function') {
    throw new Error('db must be a sequelify (or compatible) client with a query(sql, params) method');
  }
  if (!table || !colUpdate || !colCondition) {
    throw new Error('table, colUpdate and colCondition must be non-empty strings');
  }

  // Simple identifier escaper: backtick-escape and reject obviously unsafe names.
  // Adjust if your DB uses different quoting rules (e.g., double quotes).
  function escapeIdentifier(id) {
    if (typeof id !== 'string') throw new Error('Identifier must be a string');
    // disallow null bytes and newlines etc.
    if (/[\0\n\r\b\t\\'"\x1a]/.test(id)) {
      throw new Error('Identifier contains unsafe characters');
    }
    // Safe-ish: allow letters, numbers, underscore, dollar, dot (for schema.table), and backtick-escape
    // If you expect more complex identifiers (spaces, reserved words) you may want to allow them explicitly.
    const parts = id.split('.').map(part => {
      if (!/^[\w$]+$/.test(part)) {
