function addAPercentageColumn(tableData) {
    // Check if d3 is available
    if (typeof d3 === 'undefined') {
        throw new Error('d3.js library is required but not found');
    }

    // Validate input data
    if (!Array.isArray(tableData) || tableData.length === 0) {
        throw new Error('Input must be a non-empty array of objects');
    }

    // Check if required columns exist
    const firstRow = tableData[0];
    if (!firstRow.hasOwnProperty('A') || !firstRow.hasOwnProperty('sum')) {
        throw new Error('Input data must contain both "A" and "sum" columns');
    }

    // Create a deep copy to avoid mutating the original data
    const result = d3.csvParse(d3.csvFormat(tableData));

    // Add the new A_perc column to each row
    result.forEach(row => {
        // Convert values to numbers and handle potential errors
        const aValue = +row.A;
        const sumValue = +row.sum;

        if (isNaN(aValue) || isNaN(sumValue)) {
            row.A_perc = null; // Handle non-numeric values
        } else if (sumValue === 0) {
            row.A_perc = null; // Handle division by zero
        } else {
            // Calculate percentage and round to 4 decimal places
            row.A_perc = Math.round((aValue / sumValue) * 10000) / 10000;
        }
    });

    return result;
}

