 */
export async function meanAcrossTables(lst0) {
  if (!Array.isArray(lst0) || lst0.length === 0) {
    throw new Error('lst0 must be a non-empty array of 2D numeric tables.');
  }

  // Basic validation and shape detection using the first table
  const first = lst0[0];
  if (!Array.isArray(first) || first.length === 0 || !Array.isArray(first[0])) {
    throw new Error('Each table must be a non-empty 2D array.');
  }
  const rows = first.length;
  const cols = first[0].length;

  // Validate all tables have same shape and numeric entries
  for (let t = 0; t < lst0.length; ++t) {
    const table = lst0[t];
    if (!Array.isArray(table) || table.length !== rows) {
      throw new Error(`Table at index ${t} does not match expected row count ${rows}.`);
    }
    for (let r = 0; r < rows; ++r) {
      const row = table[r];
      if (!Array.isArray(row) || row.length !== cols) {
        throw new Error(`Table at index ${t}, row ${r} does not match expected column count ${cols}.`);
      }
      for (let c = 0; c < cols; ++c) {
