  // Use a tidy block to avoid leaking temporary tensors. Return a cloned tensor so
  // it survives beyond the tidy scope; then convert to array and dispose it.
  const resultTensor = tf.tidy(() => {
    const tensors = lst0.map(tbl => tf.tensor2d(tbl, [rows, cols], 'float32'));
