function firstNNotIn(primary, secondary, n, comparer) {
  primary = Array.isArray(primary) ? primary : [];
  secondary = Array.isArray(secondary) ? secondary : [];
  n = Math.max(0, Math.floor(n) || 0);

  // If n is zero, short-circuit
  if (n === 0) return [];

  // Helper default comparer (strict equality)
  var defaultComparer = function(a, b) { return a === b; };
  var cmp = typeof comparer === 'function' ? comparer : defaultComparer;

  // If linqify/linq-style API is available (Enumerable.From ...)
