// countTuples.js
// Count k-length tuples (sliding windows) in a sequence, with optional filtering, ordering, limiting.
// Uses d3-array-utils if available; otherwise falls back to a local implementation.

function countTuples(sequence, k = 2, options = {}) {
  if (!Array.isArray(sequence)) {
    throw new TypeError('sequence must be an array');
  }
  if (!Number.isInteger(k) || k < 1) {
    throw new TypeError('k must be an integer >= 1');
  }

  options = options || {};
  const keyFn = typeof options.keyFn === 'function' ? options.keyFn : defaultKeyFn;
  const filterFn = typeof options.filter === 'function' ? options.filter : null;
  const order = options.order || 'count';
  const limit = options.limit == null ? Infinity : options.limit;
  const asMap = !!options.asMap;
  const includePositions = !!options.includePositions;
  const useD3 = options.useD3 !== false; // default true: try to use d3-array-utils if available

  // Attempt to get d3-array-utils sliding/take-tuples function if requested and available.
  let d3au = null;
  if (useD3) {
    try {
      if (typeof require === 'function') {
        d3au = require('d3-array-utils');
      } else if (typeof window !== 'undefined' && window.d3_array_utils) {
        d3au = window.d3_array_utils;
      } else if (typeof window !== 'undefined' && window.d3 && window.d3.arrayUtils) {
        d3au = window.d3.arrayUtils;
      }
    } catch (e) {
      d3au = null;
    }
  }

  // Build sliding tuples array: array of {tuple: [...], index: startIndex}
  let windows;
  if (d3au && typeof d3au.tuples === 'function') {
    // if the library exposes a 'tuples' helper like d3-array-utils often does
    // d3au.tuples(sequence, k) -> array of tuples (arrays)
    const raw = d3au.tuples(sequence, k);
    windows = raw.map((t, i) => ({ tuple: t, index: i }));
  } else if (d3au && typeof d3au.slidingWindow === 'function') {
    // some variants call it slidingWindow
    const raw = d3au.slidingWindow(sequence, k);
    windows = raw.map((t, i) => ({ tuple: t, index: i }));
  } else {
    // fallback: simple slice-based sliding windows
    windows = [];
    const n = sequence.length;
    for (let i = 0; i + k <= n; i++) {
      windows.push({ tuple: sequence.slice(i, i + k), index: i });
    }
  }

  // Count occurrences. Use Map keyed by keyFn.
  const map = new Map();
  for (const { tuple, index } of windows) {
    const key = keyFn(tuple);
    const entry = map.get(key);
    if (entry) {
      entry.count += 1;
      if (includePositions) entry.positions.push(index);
    } else {
      map.set(key, {
        tuple: tuple.slice(), // copy to avoid external mutation
        key,
        count: 1,
        positions: includePositions ? [index] : undefined
      });
    }
  }

  // Convert to array for filtering/sorting/limiting
  let results = Array.from(map.values());

  // Apply filter function (tuple, count) => boolean
  if (filterFn) {
    results = results.filter(r => filterFn(r.tuple, r.count, r.key, r.positions));
  }

  // Sort
  const descDefault = order === 'count' ? true : false;
  const descending = typeof options.descending === 'boolean' ? options.descending : descDefault;

  if (typeof order === 'function') {
    results.sort((a, b) => order(a, b));
  } else if (order === 'count') {
    results.sort((a, b) => (a.count - b.count) * (descending ? -1 : 1));
  } else if (order === 'tuple') {
    // lexicographic ordering by key string
    results.sort((a, b) => {
      if (a.key < b.key) return descending ? 1 : -1;
      if (a.key > b.key) return descending ? -1 : 1;
      return 0;
    });
  } else {
    // unknown order spec: no sort
  }

  // Limit
  if (Number.isFinite(limit) && limit >= 0) {
    results = results.slice(0, limit);
  }

  // Return Map if requested (keeps ordering of results)
  if (asMap) {
    const out = new Map();
    for (const r of results) out.set(r.key, r);
    return out;
  }

  return results;

  // default key function: if all elements are primitive, join by '|', otherwise JSON.stringify
  function defaultKeyFn(tuple) {
    let allPrimitive = true;
    for (let i = 0; i < tuple.length; i++) {
      const t = tuple[i];
      const type = typeof t;
      if (t === null) continue;
      if (type === 'object' || type === 'function') {
        allPrimitive = false;
        break;
      }
    }
    if (allPrimitive) {
      // Use a separator that is unlikely to collide with typical values; user can override with keyFn
      return tuple.join('|');
    } else {
      try {
        return JSON.stringify(tuple);
      } catch (e) {
        // fallback: use toString values joined
        return tuple.map(x => String(x)).join('|');
      }
    }
  }
}

