 * @returns {DataFrame} - A new DataFrame with the added columns.
 */
function addEmptyColumns(df0, lst0, emptyValue = null, overwrite = false) {
    if (!df0 || typeof df0.count !== 'function') {
        throw new Error('df0 must be a data-forge DataFrame');
    }
    if (!Array.isArray(lst0)) {
        throw new Error('lst0 must be an array of column names');
