    const numRows = df0.count();
    let result = df0;
    const existing = new Set(result.getColumnNames());

    for (const colName of lst0) {
        if (!overwrite && existing.has(colName)) {
            // Skip existing column
            continue;
        }
        // Create a Series of length numRows filled with emptyValue
        const series = new Series({ values: Array(numRows).fill(emptyValue) });
        result = result.withSeries(colName, series);
    }

