# JavaScript Function: Sort Array A by Order in Array B

```javascript
/**
 * Sorts array A according to the order defined in array B.
 * Items in A not present in B appear at the beginning.
 * Efficient even for large arrays B using a Map for O(1) lookups.
 * 
 * @param {Array} A - The array to be sorted
 * @param {Array} B - The array defining the sort order
 * @returns {Array} - The sorted array
 */
function sortByReference(A, B) {
  // Create a Map for O(1) lookup of indices in B
  const orderMap = new Map();
  B.forEach((item, index) => {
    orderMap.set(item, index);
  });

  // Sort A based on the order defined by B
  return A.sort((a, b) => {
    const indexA = orderMap.has(a) ? orderMap.get(a) : -1;
    const indexB = orderMap.has(b) ? orderMap.get(b) : -1;

    // Items not in B (index -1) come first
    if (indexA === -1 && indexB === -1) return 0; // both not in B, maintain relative order
    if (indexA === -1) return -1; // a not in B, comes first
    if (indexB === -1) return 1;  // b not in B, comes first

    // Both in B, sort by their order in B
    return indexA - indexB;
  });
}

// Example usage:
