        case '===': return row => getPath(row, col) === val;
        case '!=': return row => getPath(row, col) != val;
        case '!==': return row => getPath(row, col) !== val;
        case '<': return row => Number(getPath(row, col)) < Number(val);
        case '<=': return row => Number(getPath(row, col)) <= Number(val);
        case '>': return row => Number(getPath(row, col)) > Number(val);
        case '>=': return row => Number(getPath(row, col)) >= Number(val);
        case 'in': return row => Array.isArray(val) && val.indexOf(getPath(row, col)) !== -1;
        case 'contains': // for strings / arrays
