            if (v == null) return false;
            const re = (val instanceof RegExp) ? val : new RegExp(val);
            return re.test(String(v));
          };
        case 'between': // val should be [min, max]
          return row => {
            const v = Number(getPath(row, col));
            return Array.isArray(val) && v >= Number(val[0]) && v <= Number(val[1]);
          };
        default:
          // fallback: equality
          return row => getPath(row, col) === val;
      }
    }

    // unknown condition type -> always true
    return () => true;
  }

  // create crossfilter instance
  const cf = CF(data);

  // create a dimension that yields the full row object so we can filter with a predicate on the row
  const dim = cf.dimension(d => d);

