const ExcelJS = require('exceljs');

/**
 * Converts multiple lists into a 2D table with specified column headers
 * @param {Array<Array>} lists - Array of lists to be converted (each inner array is a list)
 * @param {Array<string>} columnHeaders - Array of column headers
 * @param {Object} [options] - Optional configuration
 * @param {string} [options.sheetName='Sheet1'] - Name of the worksheet
 * @param {string} [options.fileName='output.xlsx'] - Output file name
 * @returns {Promise<void>} - Resolves when the Excel file is created
 */
async function listsToExcelTable(lists, columnHeaders, options = {}) {
    // Validate inputs
    if (!Array.isArray(lists) || !Array.isArray(columnHeaders)) {
        throw new Error('Both lists and columnHeaders must be arrays');
    }

    if (lists.length === 0 || columnHeaders.length === 0) {
        throw new Error('Lists and columnHeaders cannot be empty');
    }

    // Determine the number of rows and columns
    const numLists = lists.length;
    const numColumns = columnHeaders.length;

    // Check if all lists have the same length
    const listLengths = lists.map(list => list.length);
    const firstLength = listLengths[0];
    if (listLengths.some(length => length !== firstLength)) {
        throw new Error('All lists must have the same length');
    }

    // Create a new workbook
    const workbook = new ExcelJS.Workbook();
    const worksheet = workbook.addWorksheet(options.sheetName || 'Sheet1');

    // Add column headers
    worksheet.columns = columnHeaders.map(header => ({
        header: header,
        key: header.toLowerCase().replace(/\s+/g, '_')
    }));

    // Add data rows
    for (let i = 0; i < firstLength; i++) {
        const rowData = [];
        for (let j = 0; j < numLists; j++) {
            // For each list, get the i-th element
            // If the element is undefined, use empty string
            rowData.push(lists[j][i] !== undefined ? lists[j][i] : '');
        }
        worksheet.addRow(rowData);
    }

    // Auto-fit columns
    worksheet.columns.forEach(column => {
        column.width = Math.max(columnHeaderWidth(column.header), column.values.length > 0
            ? Math.max(...column.values.map(val => val.toString().length)) + 2
            : 10);
    });

    // Save the file
    const fileName = options.fileName || 'output.xlsx';
    await workbook.xlsx.writeFile(fileName);

    console.log(`Excel file "${fileName}" created successfully with ${numLists} columns and ${firstLength} rows.`);
}

/**
 * Helper function to estimate column width based on header text
 * @param {string} text - The text to measure
 * @returns {number} - Estimated column width
 */
