# Convert Lists to 2D Table with Column Headers

```javascript
const XLSX = require('xlsx');

/**
 * Converts multiple lists into a 2D table with column headers
 * @param {Array<Array>} dataLists - Array of lists to convert into table rows
 * @param {Array<string>} headers - Array of column header names
 * @returns {Object} Workbook object that can be written to file
 */
function convertListsTo2DTable(dataLists, headers) {
  // Validate inputs
  if (!Array.isArray(dataLists) || dataLists.length === 0) {
    throw new Error('dataLists must be a non-empty array');
  }

  if (!Array.isArray(headers) || headers.length === 0) {
    throw new Error('headers must be a non-empty array');
  }

  // Create 2D array with headers as first row
  const tableData = [headers];

  // Add each list as a row in the table
  for (const list of dataLists) {
    if (!Array.isArray(list)) {
      throw new Error('Each item in dataLists must be an array');
    }

    // Ensure row matches header length (pad with empty strings if needed)
    const row = [];
    for (let i = 0; i < headers.length; i++) {
      row.push(list[i] !== undefined ? list[i] : '');
    }
    tableData.push(row);
  }

  // Create a new workbook
  const workbook = XLSX.utils.book_new();

  // Convert 2D array to worksheet
  const worksheet = XLSX.utils.aoa_to_sheet(tableData);

  // Add worksheet to workbook with sheet name
  XLSX.utils.book_append_sheet(workbook, worksheet, 'Sheet1');

  return workbook;
}

/**
