    throw new TypeError('lst0 must be an array');
  }
  if (typeof var0 !== 'number' || Number.isNaN(var0)) {
    throw new TypeError('var0 must be a number');
  }
  if (var0 < 0) {
    throw new RangeError('var0 must be non-negative');
