  // Try to load ml-statistics; if not available, fall back to built-in functions.
  let meanFn, stdFn;
  try {
    const stats = require('ml-statistics');
    // common export names used by various statistic libs
    meanFn = stats.mean || stats.meanValue || stats.average || stats.avg;
    stdFn = stats.standardDeviation || stats.std || stats.sd;
  } catch (e) {
    // module not available; we'll use built-in calculations below
  }

  // Ensure we have usable mean and std functions; otherwise define them.
  if (typeof meanFn !== 'function') {
    meanFn = function(arr) {
      if (arr.length === 0) return NaN;
      let s = 0;
      for (let i = 0; i < arr.length; i++) s += arr[i];
      return s / arr.length;
    };
  }
