/**
 * Group df0 by column_name0 and sum every other numeric field per group.
 * Returns an array of objects (new table) where column_name0 is a normal column.
 *
 * @param {Array<Object>} df0 - input table (array of row objects)
 * @param {string} column_name0 - field name to group by
 * @returns {Array<Object>} - grouped & summed table
 */
function groupSumByColumn(df0, column_name0) {
  if (typeof alasql === 'undefined') {
    throw new Error('alasql library is required (alasql must be available globally).');
  }
  if (!Array.isArray(df0)) {
    throw new Error('df0 must be an array of objects (table).');
  }
  if (!df0.length) {
    return []; // empty table -> empty result
  }
  // Collect all column names present in the table
  const colsSet = df0.reduce((s, row) => {
    if (row && typeof row === 'object') {
      Object.keys(row).forEach(k => s.add(k));
    }
    return s;
  }, new Set());

  if (!colsSet.has(column_name0)) {
    // still allow grouping on missing column - result will be empty
    return [];
  }

  // Remove the grouping column from the list of columns to sum
  colsSet.delete(column_name0);
  const otherCols = Array.from(colsSet);

  // Helper to test whether a value is numeric-like
  function isNumericValue(v) {
    if (v === null || v === undefined || v === '') return false;
    // Allow numbers or numeric strings (but not pure whitespace)
    return !isNaN(Number(v));
  }

  // Determine which columns are numeric (at least one row has numeric-like value)
  const numericCols = otherCols.filter(col => df0.some(row => isNumericValue(row[col])));

  // Escape column name for alasql (wrap in [ ... ] and escape any closing bracket inside)
  function escapeColName(name) {
    return '[' + String(name).replace(/]/g, ']]') + ']';
  }

  // If no numeric columns aside from the group column, just return unique group keys with no sums
  // We'll still return the group column only
  const selectParts = [escapeColName(column_name0)];
  numericCols.forEach(col => {
    // SUM([col]) AS [col]
    selectParts.push(`SUM(${escapeColName(col)}) AS ${escapeColName(col)}`);
  });

  const query = `SELECT ${selectParts.join(', ')} FROM ? GROUP BY ${escapeColName(column_name0)}`;

  // Run query with df0 as parameter
  const result = alasql(query, [df0]);

  // Convert any null sums to 0 if desired; here we leave SQL behavior (NULL if no rows).
  // Return the result array (each element is an object with column_name0 plus summed columns)
  return result;
}
```

