function mapCategoricalToInteger(df0, colName = 'col0') {
  // Validate input
  if (!Array.isArray(df0) || df0.length === 0) {
    throw new Error('Input dataframe must be a non-empty array');
  }

  if (!(colName in df0[0])) {
    throw new Error(`Column '${colName}' not found in dataframe`);
  }

  // Extract unique categories while preserving order
  const uniqueCategories = [...new Set(df0.map(row => row[colName]))];

  // Create bidirectional mapping
  const categoryToIndex = {};
  const indexToCategory = {};

  uniqueCategories.forEach((category, index) => {
    categoryToIndex[category] = index;
    indexToCategory[index] = category;
  });

  // Create new dataframe with mapped values
  const mappedDf = df0.map(row => ({
    ...row,
    [colName]: categoryToIndex[row[colName]]
  }));

  return {
    dataframe: mappedDf,
    categoryToIndex: categoryToIndex,
    indexToCategory: indexToCategory,
    numCategories: uniqueCategories.length
  };
}

