/**
 * Remove columns that are all-zero across every record.
 *
 * Accepts either:
 *  - a pandas-core-js DataFrame instance (must implement toJSON()),
 *  - or an array of row objects ( [{col1: val1, col2: val2}, ...] ).
 *
 * Returns a new pandas-core-js DataFrame with columns removed that contain
 * only zero values in every row. A value is considered "zero" if:
 *  - it's the number 0, or
 *  - it's a numeric string that parses to 0 (e.g. "0", "0.0").
 *
 * Notes:
 *  - Empty datasets (no rows) will be returned as an empty DataFrame (no column can be
 *    proven to be "all-zero" when there are no records).
 *  - Columns containing null/undefined/empty-string/NaN/other types are NOT treated as zero.
 *
 * @param {DataFrame|Array<Object>} input - DataFrame or array of row objects
 * @returns {DataFrame} new DataFrame with all-zero columns removed
 */
function dropAllZeroColumns(input) {
  if (!input) {
    throw new Error('Input required (pandas-core-js DataFrame or array of row objects).');
  }

  // Helper: determine zeroness
  function isZeroValue(val) {
    if (typeof val === 'number') {
      return val === 0 && !Number.isNaN(val);
    }
    if (typeof val === 'string') {
      const s = val.trim();
      if (s === '') return false;         // empty string is not treated as zero
      const n = Number(s);
      return !Number.isNaN(n) && n === 0;
    }
    return false; // other types (null, undefined, boolean, object, etc.) are not zero
  }

  // Obtain rows as array of plain objects
  let rows;
  if (typeof input.toJSON === 'function') {
    // assume pandas-core-js DataFrame
    rows = input.toJSON();
  } else if (Array.isArray(input)) {
    rows = input;
  } else {
    throw new Error('Unsupported input type. Provide a DataFrame (with toJSON) or an array of row objects.');
  }

  // If no rows, return an empty DataFrame
  if (!Array.isArray(rows) || rows.length === 0) {
    return new DataFrame([]);
  }

  // Compute union of all column keys across rows (in case rows have varying keys)
  const colSet = new Set();
  for (const r of rows) {
    if (r && typeof r === 'object' && !Array.isArray(r)) {
      for (const k of Object.keys(r)) colSet.add(k);
    }
  }
  const cols = Array.from(colSet);

  // Determine which columns are ALL zero across rows
  const zeroCols = cols.filter(col => {
    // A column is "all zero" only if there is at least one row and EVERY row's value for that column is zero.
    return rows.length > 0 && rows.every(r => isZeroValue(r ? r[col] : undefined));
  });

  // Build the kept columns (cols - zeroCols)
  const zeroSet = new Set(zeroCols);
  const keptCols = cols.filter(c => !zeroSet.has(c));

  // Construct new rows keeping only keptCols
  const newRows = rows.map(r => {
    const out = {};
    for (const c of keptCols) {
      // If the original row doesn't have the column, leave value undefined (or explicitly null if you prefer)
      if (r && Object.prototype.hasOwnProperty.call(r, c)) {
        out[c] = r[c];
      } else {
        out[c] = undefined;
      }
    }
    return out;
  });

  // Return a new DataFrame constructed from filtered rows
  return new DataFrame(newRows);
}

module.exports = { dropAllZeroColumns };

