function columnsWithMissing(data, options = {}) {
  // Options:
  // - missingValues: array of tokens to treat as missing (default includes "", "NA", "N/A", "NULL", "undefined", ".", "NaN")
  // - trim: whether to trim string values before checking (default true)
  // - caseInsensitive: whether token matching is case-insensitive (default true)
  // - inputHasHeader: for array-of-arrays input, whether first row is header (default true)
  // - returnMap: if true, returns an object {colName: boolean} instead of array of names (default false)
  const cfg = Object.assign({
    missingValues: ["", "NA", "N/A", "NULL", "undefined", ".", "NaN"],
    trim: true,
    caseInsensitive: true,
    inputHasHeader: true,
    returnMap: false
  }, options);

  // Normalize tokens for comparison
  const tokenSet = new Set(
    cfg.caseInsensitive
      ? cfg.missingValues.map(t => String(t).toLowerCase())
      : cfg.missingValues.map(t => String(t))
  );

  function valueIsMissing(v) {
    if (v === null || v === undefined) return true;
    if (typeof v === 'number') return isNaN(v);
    // treat booleans as non-missing normally
    if (typeof v === 'string') {
      const s = cfg.trim ? v.trim() : v;
      const check = cfg.caseInsensitive ? s.toLowerCase() : s;
      if (tokenSet.has(check)) return true;
      // empty string also treated as missing if not already in missingValues
      if (check === '') return true;
      return false;
    }
    // other types: not missing by default
    return false;
  }

  let rows = [];
  let headers = [];

  // Handle CSV string input
  if (typeof data === 'string') {
    // parse to array of objects
    rows = d3.csvParse(data);
    // union of keys across rows to handle missing keys in some rows
    const hset = new Set();
    rows.forEach(r => Object.keys(r).forEach(k => hset.add(k)));
    headers = Array.from(hset);
  } else if (Array.isArray(data)) {
    if (data.length === 0) {
      return cfg.returnMap ? {} : [];
    }
    // array-of-arrays: decide whether first row is header
    if (Array.isArray(data[0])) {
      if (cfg.inputHasHeader) {
        headers = data[0].map(h => String(h));
        rows = data.slice(1).map(row => {
          const obj = {};
          for (let i = 0; i < headers.length; i++) {
            obj[headers[i]] = row[i];
          }
          return obj;
        });
      } else {
        // no header: name columns col1..colN using widest row length
        const maxLen = data.reduce((m, r) => Math.max(m, r.length), 0);
        headers = Array.from({ length: maxLen }, (_, i) => `col${i+1}`);
        rows = data.map(row => {
          const obj = {};
          for (let i = 0; i < maxLen; i++) obj[headers[i]] = row[i];
          return obj;
        });
      }
    } else if (typeof data[0] === 'object' && data[0] !== null) {
      // array-of-objects
      rows = data;
      const hset = new Set();
      rows.forEach(r => Object.keys(r).forEach(k => hset.add(k)));
      headers = Array.from(hset);
    } else {
      // array of primitives: treat as single column named "value"
      headers = ['value'];
      rows = data.map(v => ({ value: v }));
    }
  } else {
    throw new Error('Unsupported data type. Provide a CSV string, an array of objects, or an array-of-arrays.');
  }

  // Initialize map of missing flags
  const missingMap = {};
  headers.forEach(h => missingMap[h] = false);

  // Scan rows and mark columns that contain at least one missing value
  for (let i = 0; i < rows.length; i++) {
    const row = rows[i];
    for (let j = 0; j < headers.length; j++) {
      const h = headers[j];
      if (missingMap[h]) continue; // already found missing
      const v = row.hasOwnProperty(h) ? row[h] : undefined;
      if (valueIsMissing(v)) missingMap[h] = true;
    }
  }

