 * // Result columns in order: d, a, c, b
 */
function concatenateWithOrder(baseTable, newColumnsTable, priorityOrder) {
  // Merge the two tables horizontally
  const mergedTable = baseTable.objects().map((row, i) => ({
    ...row,
    ...newColumnsTable.objects()[i]
  }));

  const fullTable = aq.from(mergedTable);

  // Get all column names
