```javascript
const Kefir = require('kefir');

/**
 * Combines multiple input lists into a single list by following a sequence
 * that specifies which input list to draw from at each step.
 * 
 * @param {Array} inputLists - Array of lists/arrays to combine
 * @param {Array} sequence - Array of indices specifying which input list to draw from
 *                           at each step (0-based indexing)
 * @returns {Promise<Array>} Promise that resolves to the combined list
 * 
 * @example
 * const list1 = [10, 20, 30];
 * const list2 = [100, 200, 300];
 * const list3 = [1000, 2000];
 * const sequence = [0, 1, 2, 0, 1, 2, 1];
 * 
 * combineBySequence([list1, list2, list3], sequence)
 *   .then(result => console.log(result));
 *   // Output: [10, 100, 1000, 20, 200, 2000, 300]
 */
function combineBySequence(inputLists, sequence) {
  return new Promise((resolve, reject) => {
    const result = [];
    const indices = new Array(inputLists.length).fill(0);

    // Create an observable that emits for each step in the sequence
    const stream = Kefir.sequentially(0, sequence.map((listIndex, stepIndex) => ({
      listIndex,
      stepIndex
    })));

    stream
      .onValue(({ listIndex, stepIndex }) => {
        // Validate list index
        if (listIndex < 0 || listIndex >= inputLists.length) {
          throw new Error(
            `Invalid list index ${listIndex} at sequence step ${stepIndex}. ` +
            `Must be between 0 and ${inputLists.length - 1}`
          );
        }

        const currentIndex = indices[listIndex];
        const list = inputLists[listIndex];

        // Validate that the list has an element at the current index
        if (currentIndex >= list.length) {
          throw new Error(
            `List index ${listIndex} exhausted at sequence step ${stepIndex}. ` +
            `Cannot draw more elements from this list.`
          );
        }

        // Draw element from the specified list
        result.push(list[currentIndex]);
        indices[listIndex]++;
      })
      .onError(reject)
      .onEnd(() => {
        resolve(result);
      });
  });
}

// Example usage
