            convertedDates.push(null);
            continue;
        }

        try {
            // Parse with DD-MM-YYYY pattern
            const dateTime = DateTime.fromFormat(
                String(dateString).trim(), 
                'dd-MM-yyyy'
            );

            if (dateTime.isValid) {
                convertedDates.push(dateTime.toJSDate());
            } else {
                console.warn(`Invalid date at index ${i}: ${dateString}`);
                convertedDates.push(null);
                parseErrors++;
            }
        } catch (error) {
            console.warn(`Parse error at index ${i}: ${dateString}`, error);
            convertedDates.push(null);
            parseErrors++;
        }
    }

    df['Date'] = convertedDates;

    if (parseErrors > 0) {
        console.warn(`Successfully parsed ${df['Date'].length - parseErrors} dates, ${parseErrors} failed`);
    }

    return df;
}
