  // If any index is 0 => zero-based. Otherwise if all indices are >=1 and <= df0.length => treat as one-based.
  var minIdx = Math.min.apply(null, indices);
  var maxIdx = Math.max.apply(null, indices);
  if (minIdx !== 0 && minIdx >= 1 && maxIdx <= df0.length) {
    // convert one-based to zero-based
    indices = indices.map(function(v) { return v - 1; });
