      return df.map(row => ({ ...row })); // shallow copy
    }
    // array of arrays -> first row is header
    if (Array.isArray(df[0])) {
      const header = df[0].map(h => String(h));
      return df.slice(1).map(row => {
        const obj = {};
        header.forEach((h, i) => {
