Below is a self-contained Node.js function that computes a weighted average from a tabular dataset represented as an array of objects. It uses the statistics-lite library for summation. The function skips rows where either the value or weight is not a finite number. If the total weight is zero or invalid, it returns NaN.

Usage:
- rows: array of objects (each object is a row)
- colValues: string key for the value column in the row objects
- colWeights: string key for the weight column in the row objects

Code:

```javascript
const stats = require('statistics-lite');

/**
 * Compute the weighted average of entries in colValues using weights in colWeights.
 *
 * @param {Array<Object>} rows - Tabular dataset as array of row objects.
 * @param {string} colValues - Property name for the values.
 * @param {string} colWeights - Property name for the weights.
 * @returns {number} Weighted average (NaN if cannot be computed).
 */
function weightedAverage(rows, colValues, colWeights) {
  if (!Array.isArray(rows)) {
    throw new TypeError('rows must be an array of objects');
  }
  if (typeof colValues !== 'string' || typeof colWeights !== 'string') {
    throw new TypeError('colValues and colWeights must be string property names');
  }

  const values = [];
  const weights = [];

  for (let i = 0; i < rows.length; i++) {
    const row = rows[i];
    if (row == null || typeof row !== 'object') continue;

    const v = Number(row[colValues]);
    const w = Number(row[colWeights]);

    // Only include pairs where both value and weight are finite numbers
    if (Number.isFinite(v) && Number.isFinite(w)) {
      values.push(v);
      weights.push(w);
    }
  }

  if (weights.length === 0) {
    return NaN; // no valid pairs
  }

  const numerator = stats.sum(values.map((val, idx) => val * weights[idx]));
  const denominator = stats.sum(weights);

  if (!Number.isFinite(denominator) || denominator === 0) {
    return NaN; // cannot divide by zero or invalid total weight
  }

  return numerator / denominator;
}

