    centroids = updateCentroids(arr0, labels, numClusters);

    // Check for convergence
    let converged = true;
    for (let i = 0; i < centroids.length; i++) {
      if (Math.abs(centroids[i] - prevCentroids[i]) > tolerance) {
        converged = false;
        break;
      }
    }

    if (converged) break;

    // Reassign clusters
    labels = assignClusters(arr0, centroids);
    prevCentroids = [...centroids];
  }

