  const NS_PER_SECOND = 1e9;
  const SECONDS_PER_DAY = 24 * 3600;
  const NS_PER_DAY = SECONDS_PER_DAY * NS_PER_SECOND;

  return df0.map(row => {
    const v0 = row[col0];
    const v1 = row[col1];

    // Prepare a copy of the row to avoid mutating input
    const outRow = { ...row };

