function findNearestIndex(lst0, lst1, var0, var1) {
  if (!Array.isArray(lst0) || !Array.isArray(lst1)) {
    throw new TypeError('lst0 and lst1 must be arrays');
  }
  if (lst0.length !== lst1.length) {
    throw new Error('lst0 and lst1 must have the same length');
  }
  const n = lst0.length;
  if (n === 0) return -1;

  // Build points with x,y and original index
  const points = new Array(n);
  for (let i = 0; i < n; i++) {
    points[i] = { x: Number(lst0[i]), y: Number(lst1[i]), idx: i };
  }

  // Euclidean distance function (returns true distance)
  const distance = (a, b) => {
    const dx = a.x - b.x;
    const dy = a.y - b.y;
    return Math.hypot(dx, dy);
  };

  // Try to load kd-tree-javascript-lite (CommonJS). If unavailable, use local KDTreeLite.
  let KDTreeConstructor = null;
  try {
    const lib = require('kd-tree-javascript-lite');
    // library might export the constructor directly or as a property
    KDTreeConstructor = lib && (lib.KDTree || lib);
  } catch (e) {
    KDTreeConstructor = null;
  }

  // Lightweight KD-tree implementation (mimics kd-tree-javascript's constructor/neareset API)
  class KDTreeLite {
    constructor(pointsArr, distFunc, dimensions) {
      this.dimensions = dimensions.slice();
      this.dist = distFunc;
      this.root = this._buildTree(pointsArr, 0);
    }

    _buildTree(pointsArr, depth) {
      if (!pointsArr || pointsArr.length === 0) return null;
      const axis = this.dimensions[depth % this.dimensions.length];
      // sort and pick median (simple; O(n log n) build)
      pointsArr.sort((a, b) => a[axis] - b[axis]);
      const median = Math.floor(pointsArr.length / 2);
      const node = {
        point: pointsArr[median],
        axis: axis,
        left: this._buildTree(pointsArr.slice(0, median), depth + 1),
        right: this._buildTree(pointsArr.slice(median + 1), depth + 1)
      };
      return node;
    }

    // nearest(point, maxNodes) returns array of [point, distance], sorted ascending by distance
    nearest(searchPoint, maxNodes) {
      const bestNodes = [];

      const saveNode = (nodePoint, nodeDist) => {
        if (bestNodes.length < maxNodes) {
          bestNodes.push([nodePoint, nodeDist]);
          if (bestNodes.length === maxNodes) {
            // maintain max-heap behavior: keep the furthest at front for easy eviction
            bestNodes.sort((a, b) => b[1] - a[1]);
          }
        } else if (nodeDist < bestNodes[0][1]) {
          // replace furthest
          bestNodes[0] = [nodePoint, nodeDist];
          bestNodes.sort((a, b) => b[1] - a[1]);
        }
      };

      const recursiveSearch = (node) => {
        if (!node) return;
        const point = node.point;
        const axis = node.axis;
        const ownDist = this.dist(point, searchPoint);
        saveNode(point, ownDist);

        const diff = searchPoint[axis] - point[axis];
        const nearSide = diff <= 0 ? node.left : node.right;
        const farSide = diff <= 0 ? node.right : node.left;

        // explore near side first
        recursiveSearch(nearSide);

        // check if we need to explore the far side
        let bestDist = Infinity;
        if (bestNodes.length > 0) {
          // current worst distance among best nodes
          bestDist = bestNodes[0][1];
        }
        if (bestNodes.length < maxNodes || Math.abs(diff) < bestDist) {
          recursiveSearch(farSide);
        }
      };

      recursiveSearch(this.root);
      // return sorted ascending
      return bestNodes.sort((a, b) => a[1] - b[1]);
    }
  }

  // Choose constructor
  const KDTree = KDTreeConstructor || KDTreeLite;
  const tree = new KDTree(points.slice(), distance, ['x', 'y']);

  const nearest = tree.nearest({ x: var0, y: var1 }, 1);
  if (!nearest || nearest.length === 0) return -1;
  return nearest[0][0].idx;
}
