```javascript
// Ensure you have the wink-tokenise library loaded
const winkTokenise = require('wink-tokenise'); // Make sure to install the library using npm

function extractSurroundingWords(text, searchTerm, numWords) {
    // Tokenize the input text
    const tokeniser = winkTokenise();
    const tokens = tokeniser.tokenize(text);

    // Find the index of the search term
    const searchTermIndex = tokens.findIndex(token => token.value.toLowerCase() === searchTerm.toLowerCase());

    // If the search term is not found, return None for both sides
    if (searchTermIndex === -1) {
        return {
            before: Array(numWords).fill('None'),
            after: Array(numWords).fill('None')
        };
    }

    // Find the words before and after the search term
    const before = [];
    const after = [];

    // Extract preceding words
    for (let i = 1; i <= numWords; i++) {
        if (searchTermIndex - i >= 0) {
            before.unshift(tokens[searchTermIndex - i].value);
        } else {
            before.unshift('None'); // Substitute None if there are not enough words
        }
    }

    // Extract following words
    for (let i = 1; i <= numWords; i++) {
        if (searchTermIndex + i < tokens.length) {
            after.push(tokens[searchTermIndex + i].value);
        } else {
            after.push('None'); // Substitute None if there are not enough words
        }
    }

    return {
        before: before,
        after: after
    };
}

