    orderBy = 'count',
    orderDirection = 'desc',
    limit = null
  } = options;

  // Validate input
  if (!Array.isArray(sequence)) {
    throw new TypeError('Input must be an array');
  }

  // Count occurrences using rollup
  const counts = rollup(
    sequence,
    v => v.length, // Count occurrences
    d => JSON.stringify(d) // Use JSON string as key for proper tuple comparison
  );

  // Convert Map to array of [tuple, count] pairs
  let results = Array.from(counts, ([key, count]) => [
    JSON.parse(key), // Convert back to original tuple
    count
  ]);

  // Apply filtering if provided
  if (typeof filter === 'function') {
    results = results.filter(filter);
  }

  // Apply ordering
  if (typeof orderBy === 'function') {
    results = sort(results, orderBy);
  } else if (orderBy === 'tuple') {
    results = sort(results, (a, b) => {
      const compare = ascending(JSON.stringify(a[0]), JSON.stringify(b[0]));
