      message: 'must be a safe integer number'
    });

  // a two-item grouping (tuple) [wideInt, standardInt]
  const pair = z.tuple([wideInt, standardInt]);

  // collection of pairs
  const schema = z.array(pair);

  const result = schema.safeParse(collection);
  return result.success;
