Here's a self-contained JavaScript function that generates all possible sequences by picking exactly one element from each sublist:

```javascript
const C = require('js-combinators');

function cartesianProduct(lst0) {
  if (!lst0 || lst0.length === 0) {
    return [[]];
  }

  // Start with the first sublist, mapping each element to a single-element array
  let result = lst0[0].map(elem => [elem]);

  // For each subsequent sublist, combine with previous results
  for (let i = 1; i < lst0.length; i++) {
    result = C.flatMap(
      prev => C.map(
        elem => [...prev, elem],
        lst0[i]
      ),
      result
    );
  }

  return result;
}

